// - запуск только при QA_REAL_WRITE=1 (иначе test.skip); черновик удаляется в afterEach.
import { expect, Page } from '@playwright/test';
import { Ctl, LOAD, goToPhotosStep, interceptDraft } from '../addbusiness-photos-step/photos-step.helpers';

export { LOAD, REAL_WRITE, deleteDraft } from '../addbusiness-photos-step/photos-step.helpers';
export type { Ctl } from '../addbusiness-photos-step/photos-step.helpers';

export const SKIP_REASON =
  'Пишет на прод (черновик объявления «QA-TEST» под user, удаляется в afterEach; /api/payments обрывается). Запуск только с QA_REAL_WRITE=1.';

export const FREE = 'חבילה 1 – הכרות חינם';
export const PKG2 = 'חבילה 2 – מומלצת!';
export const PKG3 = 'חבילה 3 – למכור מהר!';
/** Подпись поля после #2e5dd0 — без «מס» и без «(לא חובה)». */
export const FIELD_LABEL = 'שם לחשבונית';
/** Старая подпись (#8bea2a) — на сайте её быть не должно (#2e5dd0). */
export const OLD_LABEL_RE = /שם לחשבונית מס|\(לא חובה\)/;
export const FIELD_PLACEHOLDER = 'השם שיופיע בחשבונית';
export const CATEGORY = 'בתי קפה ומסעדות';

const isPayments = (url: string) => /\/api\/payments(\?|$|\/)/.test(url);

export type PayCtl = Ctl & {
  /** Тела перехваченных POST /api/payments (все оборваны). */
  payments: unknown[];
};

/** Блок записи как в #def18b + перехват /api/payments (тело → payments[], запрос → abort). */
export async function interceptWithPayments(page: Page): Promise<PayCtl> {
  const ctl = (await interceptDraft(page, '8bea2a')) as PayCtl;
  ctl.payments = [];
  // Зарегистрирован позже общего обработчика — срабатывает первым.
  await page.route(isPayments, async (route) => {
    const req = route.request();
    if (req.method() === 'POST') {
      let body: unknown = req.postData();
      try {
        body = req.postDataJSON();
      } catch {
        /* не JSON — оставить строкой */
      }
      ctl.payments.push(body);
    }
    if (['GET', 'HEAD', 'OPTIONS'].includes(req.method())) return route.fallback();
    return route.abort('blockedbyclient');
  });
  return ctl;
}

/** Поле счёта: input#invoice-name (по подписи). */
export const invoiceField = (page: Page) => page.getByLabel(FIELD_LABEL);

/** Шаги 1–3 (через помощник #def18b) → шаг 4 «בחר חבילת פרסום». */
export async function goToPackageStep(page: Page, ctl: Ctl) {
  await goToPhotosStep(page, ctl, CATEGORY);
  await page.getByRole('button', { name: 'שלב הבא' }).click();
  await expect(page.getByText('בחר חבילת פרסום'), 'шаг 4 — выбор пакета').toBeVisible(LOAD);
}

/** На шаге 4 выбрать пакет по названию (карточка role=button c заголовком пакета) → «שלב הבא» → шаг 5 «פרסום המודעה». */
export async function choosePackageAndGoToStep5(page: Page, pkg: string) {
  const card = page.getByRole('button').filter({ has: page.getByRole('heading', { name: pkg, exact: true }) });
  await card.click();
  await expect(card, `пакет «${pkg}» выбран`).toHaveAttribute('aria-pressed', 'true');
  await page.getByRole('button', { name: 'שלב הבא' }).click();
  await expect(page.getByText('סיכום אפשרויות הפרסום'), 'шаг 5 «פרסום המודעה» — сводка').toBeVisible(LOAD);
  await expect(page.getByText(pkg).first(), `в сводке шага 5 — «${pkg}»`).toBeVisible();
}

/** С шага 5 «חזרה» → шаг 4 → другой пакет → шаг 5. */
export async function switchPackage(page: Page, pkg: string) {
  await page.getByRole('button', { name: 'חזרה' }).click();
  await expect(page.getByText('בחר חבילת פרסום'), 'вернулись на шаг 4').toBeVisible(LOAD);
  await choosePackageAndGoToStep5(page, pkg);
}

/** Поле есть и соответствует тикетам (#8bea2a «מה רצוי» + комментарий программиста; подпись — #2e5dd0). */
export async function expectFieldShown(page: Page) {
  const field = invoiceField(page);
  await expect(field, 'поле «שם לחשבונית» видно').toBeVisible();
  await expect(field).toHaveAttribute('id', 'invoice-name');
  const label = page.locator('label[for="invoice-name"]');
  // #2e5dd0: подпись ровно «שם לחשבונית» — без «מס» и без «(לא חובה)»; поле по-прежнему не обязательное.
  await expect(label, 'подпись «שם לחשבונית» (#2e5dd0)').toHaveText(/^\s*שם לחשבונית\s*$/);
  await expect(label, 'нет «מס» / «(לא חובה)» в подписи (#2e5dd0)').not.toHaveText(OLD_LABEL_RE);
  await expect(page.getByText(/שם לחשבונית מס/), 'старой подписи «שם לחשבונית מס» на шаге 5 нет (#2e5dd0)').toHaveCount(0);
  await expect(field).toHaveAttribute('placeholder', FIELD_PLACEHOLDER);
  await expect(field).toHaveAttribute('maxlength', '100');
  await expect(field, 'нет aria-required').not.toHaveAttribute('aria-required');
  expect(await field.evaluate((el: HTMLInputElement) => el.required), 'required = false').toBe(false);
  expect(
    await field.evaluate((el) => getComputedStyle(el).direction),
    'направление rtl',
  ).toBe('rtl');
}

export async function expectFieldHidden(page: Page) {
  await expect(page.locator('#invoice-name'), 'поля #invoice-name нет').toHaveCount(0);
  await expect(page.getByText(FIELD_LABEL), 'текста «שם לחשבונית» нет').toHaveCount(0);
}

/** Отметить оба подтверждения шага 5 и нажать «שלח»; дождаться перехваченного POST /api/payments. */
export async function confirmAndSubmit(page: Page, ctl: PayCtl) {
  await page.getByLabel(/אישור פרסום/).check();
  await page.getByLabel(/קראתי והבנתי את תקנון האתר/).check();
  const send = page.getByRole('button', { name: 'שלח', exact: true });
  await expect(send, '«שלח» активна').toBeEnabled();
  const paymentReq = page.waitForRequest((r) => r.method() === 'POST' && isPayments(r.url()), LOAD);
  await send.click();
  await paymentReq;
  await expect.poll(() => ctl.payments.length, { message: 'POST /api/payments перехвачен (и оборван)' }).toBe(1);
}

/** customerName из тела /api/payments (на любом уровне вложенности). */
export function findCustomerName(body: unknown): unknown {
  if (!body || typeof body !== 'object') return undefined;
  const obj = body as Record<string, unknown>;
  if ('customerName' in obj) return obj.customerName;
  for (const v of Object.values(obj)) {
    const found = findCustomerName(v);
    if (found !== undefined) return found;
  }
  return undefined;
}
